const items = $input.all();

if (items.length === 0) {
  return [];
}

const opportunity = items[0].json;

const companyName = String(
  opportunity.company_name ?? ''
).trim();

const companyDomain = String(
  opportunity.company_domain ?? ''
).trim();

const positionTitle = String(
  opportunity.position_title ?? ''
)
  .replace(/\s+/g, ' ')
  .trim();

const queries = [
  {
    query_type: 'RECRUITING',
    search_query:
      `"${companyName}" ${companyDomain} recruiter talent hiring`,
  },
  {
    query_type: 'TECHNICAL_LEADERSHIP',
    search_query:
      `"${companyName}" ${companyDomain} CTO "Head of Engineering" engineering lead`,
  },
  {
    query_type: 'FOUNDERS',
    search_query:
      `"${companyName}" ${companyDomain} founder co-founder CEO`,
  },
  {
    query_type: 'LINKEDIN_PEOPLE',
    search_query:
      `site:linkedin.com/in "${companyName}" engineering`,
  },
  {
    query_type: 'VACANCY_CONTACT',
    search_query:
      `"${positionTitle}" "${companyName}" recruiter hiring manager`,
  },
  {
    query_type: 'COMPANY_TEAM',
    search_query:
      `site:${companyDomain} team about leadership people`,
  },
];

return queries.map((query, index) => ({
  json: {
    ...opportunity,

    search_query_id:
      `${opportunity.opportunity_key}::${query.query_type.toLowerCase()}`,

    query_number: index + 1,
    query_type: query.query_type,
    search_query: query.search_query,
  },
}));

const responses = $input.all();
const queryItems =
  $('Generate Contact Search Queries').all();

function cleanText(value) {
  return String(value ?? '')
    .replace(/<[^>]*>/g, ' ')
    .replace(/&quot;/gi, '"')
    .replace(/&#39;/gi, "'")
    .replace(/&amp;/gi, '&')
    .replace(/&nbsp;/gi, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function getDomain(value) {
  const url = String(value ?? '').trim();

  const match = url.match(
    /^https?:\/\/([^/?#]+)/i
  );

  if (!match) {
    return '';
  }

  return match[1]
    .toLowerCase()
    .replace(/^www\./, '')
    .replace(/:\d+$/, '');
}

const output = [];

for (let responseIndex = 0;
  responseIndex < responses.length;
  responseIndex++) {

  const response =
    responses[responseIndex]?.json ?? {};

  const query =
    queryItems[responseIndex]?.json ?? {};

  const results =
    Array.isArray(response.web?.results)
      ? response.web.results
      : [];

  for (let resultIndex = 0;
    resultIndex < results.length;
    resultIndex++) {

    const result = results[resultIndex] ?? {};

    const sourceUrl =
      String(result.url ?? '').trim();

    if (!sourceUrl) {
      continue;
    }

    const sourceDomain =
      getDomain(sourceUrl);

    const companyDomain =
      String(query.company_domain ?? '')
        .trim()
        .toLowerCase()
        .replace(/^www\./, '');

    const extraSnippets =
      Array.isArray(result.extra_snippets)
        ? result.extra_snippets
            .map(cleanText)
            .filter(Boolean)
        : [];

    let sourceType = 'OTHER';

    if (
      /^https?:\/\/(www\.)?linkedin\.com\/in\//i
        .test(sourceUrl)
    ) {
      sourceType = 'LINKEDIN_PERSON';
    } else if (
      /^https?:\/\/(www\.)?linkedin\.com\/company\//i
        .test(sourceUrl)
    ) {
      sourceType = 'LINKEDIN_COMPANY';
    } else if (
      sourceDomain === companyDomain ||
      sourceDomain.endsWith(`.${companyDomain}`)
    ) {
      sourceType = 'COMPANY_SITE';
    } else if (
      result.subtype === 'article' ||
      result.article
    ) {
      sourceType = 'ARTICLE';
    }

    const sourceTitle =
      cleanText(result.title);

    const sourceDescription =
      cleanText(result.description);

    const evidenceText = [
      ...new Set([
        sourceTitle,
        sourceDescription,
          ...extraSnippets,
      ].filter(Boolean)),
    ].join('\n');

    output.push({
      json: {
        row_number: query.row_number,

        opportunity_key:
          query.opportunity_key,

        company_key:
          query.company_key,

        company_name:
          query.company_name,

        company_domain:
          query.company_domain,

        country:
          query.country,

        position_title:
          query.position_title,

        vacancy_url:
          query.vacancy_url,

        careers_contact_email:
          query.careers_contact_email,

        search_query_id:
          query.search_query_id,

        query_number:
          query.query_number,

        query_type:
          query.query_type,

        search_query:
          query.search_query,

        result_rank:
          resultIndex + 1,

        source_title: sourceTitle,
        source_url: sourceUrl,
        source_domain: sourceDomain,
        source_type: sourceType,

        source_description:
          sourceDescription,

        extra_snippets:
          extraSnippets.join(' | '),

        evidence_text:
          evidenceText,

        source_page_age:
          result.page_age ??
          result.age ??
          '',
      },
    });
  }
}

return output;

const items = $input.all();

if (items.length === 0) {
  return [];
}

function cleanText(value) {
  return String(value ?? '')
    .replace(/\s+/g, ' ')
    .trim();
}

function normalizeUrl(value) {
  return String(value ?? '')
    .trim()
    .replace(/\/+$/, '')
    .toLowerCase();
}

const base = items[0].json;
const groupedSources = new Map();

for (const item of items) {
  const result = item.json ?? {};

  const sourceUrl =
    String(result.source_url ?? '').trim();

  if (!sourceUrl) {
    continue;
  }

  const sourceKey = normalizeUrl(sourceUrl);

  if (!groupedSources.has(sourceKey)) {
    groupedSources.set(sourceKey, {
      source_title:
        cleanText(result.source_title),

      source_url: sourceUrl,

      source_domain:
        cleanText(result.source_domain),

      source_type:
        cleanText(result.source_type) || 'OTHER',

      source_page_age:
        cleanText(result.source_page_age),

      query_types: new Set(),

      evidence_parts: new Set(),
    });
  }

  const source = groupedSources.get(sourceKey);

  if (result.query_type) {
    source.query_types.add(
      cleanText(result.query_type)
    );
  }

  if (
    source.source_type === 'OTHER' &&
    result.source_type &&
    result.source_type !== 'OTHER'
  ) {
    source.source_type =
      cleanText(result.source_type);
  }

  const evidence =
    String(result.evidence_text ?? '').trim();

  if (evidence) {
    source.evidence_parts.add(evidence);
  }
}

const evidenceSources = [
  ...groupedSources.values(),
].map((source, index) => ({
  source_id: `S${index + 1}`,

  source_title:
    source.source_title,

  source_url:
    source.source_url,

  source_domain:
    source.source_domain,

  source_type:
    source.source_type,

  source_page_age:
    source.source_page_age,

  query_types:
    [...source.query_types].join(' | '),

  evidence_text:
    [...source.evidence_parts]
      .join('\n')
      .slice(0, 5000),
}));

const evidenceBundle = evidenceSources
  .map(source => {
    return [
      `[${source.source_id}]`,
      `Title: ${source.source_title}`,
      `URL: ${source.source_url}`,
      `Source type: ${source.source_type}`,
      `Search categories: ${source.query_types}`,
      `Date: ${source.source_page_age}`,
      `Evidence: ${source.evidence_text}`,
    ]
      .filter(line => !line.endsWith(': '))
      .join('\n');
  })
  .join('\n\n');

return [
  {
    json: {
      row_number:
        base.row_number,

      opportunity_key:
        base.opportunity_key,

      company_key:
        base.company_key,

      company_name:
        base.company_name,

      company_domain:
        base.company_domain,

      country:
        base.country,

      position_title:
        base.position_title,

      vacancy_url:
        base.vacancy_url,

      careers_contact_email:
        base.careers_contact_email,

      evidence_source_count:
        evidenceSources.length,

      evidence_sources:
        evidenceSources,

      evidence_bundle:
        evidenceBundle,
    },
  },
];

const aiItems = $input.all();
const evidenceItems =
  $('Prepare Contact Evidence').all();

function cleanText(value) {
  return String(value ?? '')
    .replace(/\s+/g, ' ')
    .trim();
}

function normalizeEmail(value) {
  return cleanText(value).toLowerCase();
}

function normalizeUrl(value) {
  return cleanText(value)
    .replace(/\/+$/, '');
}

function normalizeKeyPart(value) {
  return cleanText(value)
    .toLowerCase()
    .replace(/[^a-z0-9@._-]+/g, '-')
    .replace(/^-+|-+$/g, '');
}

const rolePriorities = {
  RECRUITER: 1,
  TECHNICAL_LEADER: 2,
  TECHNICAL_FOUNDER: 3,
  CEO_FOUNDER: 4,
  OTHER_EMPLOYEE: 5,
};

const output = [];

for (let index = 0;
  index < aiItems.length;
  index++) {

  const aiOutput =
    aiItems[index]?.json?.output ?? {};

  const base =
    evidenceItems[index]?.json ?? {};

  const candidates =
    Array.isArray(aiOutput.candidates)
      ? aiOutput.candidates
      : [];

  for (const candidate of candidates) {
    const contactName =
      cleanText(candidate.contact_name);

    if (!contactName) {
      continue;
    }

    const contactEmail =
      normalizeEmail(candidate.contact_email);

    const linkedinUrl =
      normalizeUrl(
        candidate.contact_linkedin_url
      );

    const contactRole =
      cleanText(candidate.contact_role);

    const roleCategory =
      cleanText(candidate.role_category);

    const identity =
      contactEmail ||
      linkedinUrl ||
      contactRole ||
      contactName;

    const sourceUrls =
      Array.isArray(candidate.source_urls)
        ? candidate.source_urls
            .map(normalizeUrl)
            .filter(Boolean)
        : [];

    const sourceIds =
      Array.isArray(candidate.source_ids)
        ? candidate.source_ids
            .map(cleanText)
            .filter(Boolean)
        : [];

    output.push({
      json: {
        contact_key: [
          base.opportunity_key,
          normalizeKeyPart(contactName),
          normalizeKeyPart(identity),
        ].join('::'),

        opportunity_key:
          base.opportunity_key,

        company_key:
          base.company_key,

        company_name:
          base.company_name,

        company_domain:
          base.company_domain,

        position_title:
          base.position_title,

        contact_name:
          contactName,

        contact_role:
          contactRole,

        contact_email:
          contactEmail,

        contact_linkedin_url:
          linkedinUrl,

        role_category:
          roleCategory,

        role_priority:
          rolePriorities[roleCategory] ?? 5,

        current_company_confirmed:
          candidate.current_company_confirmed === true,

        vacancy_connection:
          candidate.vacancy_connection === true,

        general_hiring_connection:
          candidate.general_hiring_connection === true,

        source_ids:
          sourceIds.join(' | '),

        source_urls:
          sourceUrls.join(' | '),

        source_url:
          sourceUrls[0] || '',

        source_type:
          'BRAVE_AI_EXTRACTED',

        evidence:
          cleanText(
            candidate.evidence_summary
          ),

        email_confidence: '',

        contact_score: '',

        selection_status:
          'CANDIDATE',

        research_status:
          contactEmail || linkedinUrl
            ? 'FOUND'
            : 'PARTIAL',

        last_checked:
          new Date().toISOString(),
      },
    });
  }
}

return output;

const verificationItems = $input.all();

const candidateItems =
  $('Create Contact Candidate Rows').all();

const evidencePackage =
  $('Prepare Contact Evidence').first().json;

function cleanText(value) {
  return String(value ?? '')
    .replace(/\s+/g, ' ')
    .trim();
}

function normalizeEmail(value) {
  return cleanText(value).toLowerCase();
}

const verificationByEmail = new Map();

for (const item of verificationItems) {
  const data = item.json?.data ?? {};

  const email =
    normalizeEmail(data.email);

  if (!email) {
    continue;
  }

  verificationByEmail.set(email, data);
}

const evidenceById = new Map(
  (
    Array.isArray(
      evidencePackage.evidence_sources
    )
      ? evidencePackage.evidence_sources
      : []
  ).map(source => [
    cleanText(source.source_id),
    source,
  ])
);

function calculateFreshness(candidate) {
  const sourceIds = cleanText(
    candidate.source_ids
  )
    .split('|')
    .map(value => value.trim())
    .filter(Boolean);

  const dates = [];

  for (const sourceId of sourceIds) {
    const source = evidenceById.get(sourceId);

    const rawDate =
      cleanText(source?.source_page_age);

    if (!rawDate) {
      continue;
    }

    const parsedDate = new Date(rawDate);

    if (!Number.isNaN(parsedDate.getTime())) {
      dates.push(parsedDate);
    }
  }

  if (dates.length === 0) {
    return {
      score: 4,
      newest_date: '',
    };
  }

  dates.sort((a, b) => b - a);

  const newestDate = dates[0];

  const ageDays =
    (Date.now() - newestDate.getTime()) /
    (1000 * 60 * 60 * 24);

  let score = 1;

  if (ageDays <= 90) {
    score = 10;
  } else if (ageDays <= 365) {
    score = 7;
  } else if (ageDays <= 730) {
    score = 4;
  }

  return {
    score,
    newest_date:
      newestDate.toISOString(),
  };
}

const roleScores = {
  RECRUITER: 35,
  TECHNICAL_LEADER: 33,
  TECHNICAL_FOUNDER: 30,
  CEO_FOUNDER: 26,
  OTHER_EMPLOYEE: 15,
};

const output = [];

for (const item of candidateItems) {
  const candidate = item.json ?? {};

  const email =
    normalizeEmail(candidate.contact_email);

  if (!email) {
    continue;
  }

  const verification =
    verificationByEmail.get(email) ?? {};

  const hunterStatus =
    cleanText(verification.status)
      .toLowerCase();

  const hunterScore =
    Number(verification.score ?? 0);

  const acceptAll =
    verification.accept_all === true;

  const smtpCheck =
    verification.smtp_check === true;

  let emailConfidence = 'LOW';
  let emailVerificationScore = 0;

  if (
    hunterStatus === 'valid' &&
    !acceptAll &&
    smtpCheck &&
    hunterScore >= 80
  ) {
    emailConfidence = 'HIGH';
    emailVerificationScore = 15;
  } else if (
    hunterStatus === 'valid'
  ) {
    emailConfidence = 'MEDIUM';
    emailVerificationScore = 10;
  } else if (
    hunterStatus === 'accept_all' ||
    hunterStatus === 'unknown'
  ) {
    emailConfidence = 'LOW';
    emailVerificationScore = 4;
  } else {
    emailConfidence = 'NONE';
    emailVerificationScore = 0;
  }

  const roleRelevanceScore =
    roleScores[candidate.role_category] ?? 15;

  const companyConfirmationScore =
    candidate.current_company_confirmed === true
      ? 25
      : 0;

  let hiringConnectionScore = 0;

  if (
    candidate.vacancy_connection === true
  ) {
    hiringConnectionScore = 15;
  } else if (
    candidate.general_hiring_connection === true
  ) {
    hiringConnectionScore = 8;
  }

  const freshness =
    calculateFreshness(candidate);

  const contactScore = Math.min(
    100,
    roleRelevanceScore +
      companyConfirmationScore +
      hiringConnectionScore +
      emailVerificationScore +
      freshness.score
  );

  output.push({
    json: {
      ...candidate,

      hunter_status:
        hunterStatus,

      hunter_score:
        hunterScore,

      hunter_accept_all:
        acceptAll,

      hunter_smtp_check:
        smtpCheck,

      email_confidence:
        emailConfidence,

      role_relevance_score:
        roleRelevanceScore,

      company_confirmation_score:
        companyConfirmationScore,

      hiring_connection_score:
        hiringConnectionScore,

      email_verification_score:
        emailVerificationScore,

      evidence_freshness_score:
        freshness.score,

      newest_evidence_date:
        freshness.newest_date,

      contact_score:
        contactScore,

      source_type:
        'BRAVE_HUNTER_VERIFIED',

      last_checked:
        new Date().toISOString(),
    },
  });
}

return output;

function cleanText(value) {
  return String(value ?? '')
    .replace(/\s+/g, ' ')
    .trim();
}

function normalizeEmail(value) {
  return cleanText(value).toLowerCase();
}

const finderResponse = $json ?? {};
const finderData = finderResponse.data ?? {};
const finderParams = finderResponse.meta?.params ?? {};

let candidate = {};

// First try n8n's item-linking.
try {
  candidate =
    $('Create Contact Candidate Rows').item.json ?? {};
} catch {
  candidate = {};
}

// Fallback: match using the person's name and company domain.
if (!candidate.contact_name) {
  const searchedName =
    cleanText(
      finderParams.full_name ??
      `${finderParams.first_name ?? ''} ${finderParams.last_name ?? ''}`
    ).toLowerCase();

  const searchedDomain =
    cleanText(finderParams.domain).toLowerCase();

  const candidates =
    $('Create Contact Candidate Rows').all();

  const match = candidates.find(item => {
    const row = item.json ?? {};

    return (
      cleanText(row.contact_name).toLowerCase() === searchedName &&
      cleanText(row.company_domain).toLowerCase() === searchedDomain
    );
  });

  candidate = match?.json ?? {};
}

if (!candidate.contact_name) {
  throw new Error(
    'Unable to reconnect the Hunter result to its contact candidate.'
  );
}

const foundEmail =
  normalizeEmail(finderData.email);

const verificationStatus =
  cleanText(
    finderData.verification?.status
  ).toLowerCase();

return {
  json: {
    ...candidate,

    contact_email:
      foundEmail || candidate.contact_email || '',

    email_finder_result:
      foundEmail ? 'FOUND' : 'NOT_FOUND',

    hunter_finder_score:
      Number(finderData.score ?? 0),

    hunter_finder_status:
      verificationStatus,

    hunter_finder_accept_all:
      finderData.accept_all === true,

    hunter_finder_source_type:
      cleanText(finderData.source_type),

    hunter_finder_sources_count:
      Array.isArray(finderData.sources)
        ? finderData.sources.length
        : 0,

    last_checked:
      new Date().toISOString(),
  },
};

function cleanText(value) {
  return String(value ?? '')
    .replace(/\s+/g, ' ')
    .trim();
}

function normalizeEmail(value) {
  return cleanText(value).toLowerCase();
}

const verification = $json?.data ?? {};

let candidate = {};

try {
  candidate = $('Attach Found Email').item.json ?? {};
} catch {
  candidate = {};
}

// Fallback when n8n item linking is unavailable
if (!candidate.contact_name) {
  const verifiedEmail =
    normalizeEmail(verification.email);

  const match = $('Attach Found Email')
    .all()
    .find(item =>
      normalizeEmail(item.json.contact_email) ===
      verifiedEmail
    );

  candidate = match?.json ?? {};
}

if (!candidate.contact_name) {
  throw new Error(
    'Unable to reconnect the verified email to its candidate.'
  );
}

const evidencePackage =
  $('Prepare Contact Evidence').first().json;

const evidenceSources =
  Array.isArray(evidencePackage.evidence_sources)
    ? evidencePackage.evidence_sources
    : [];

const evidenceById = new Map(
  evidenceSources.map(source => [
    cleanText(source.source_id),
    source,
  ])
);

function calculateFreshness(sourceIdsValue) {
  const sourceIds = cleanText(sourceIdsValue)
    .split('|')
    .map(value => value.trim())
    .filter(Boolean);

  const dates = [];

  for (const sourceId of sourceIds) {
    const rawDate = cleanText(
      evidenceById.get(sourceId)?.source_page_age
    );

    if (!rawDate) {
      continue;
    }

    const parsedDate = new Date(rawDate);

    if (!Number.isNaN(parsedDate.getTime())) {
      dates.push(parsedDate);
    }
  }

  if (dates.length === 0) {
    return {
      score: 4,
      newest_date: '',
    };
  }

  dates.sort((a, b) => b - a);

  const newestDate = dates[0];

  const ageDays =
    (Date.now() - newestDate.getTime()) /
    (1000 * 60 * 60 * 24);

  let score = 1;

  if (ageDays <= 90) {
    score = 10;
  } else if (ageDays <= 365) {
    score = 7;
  } else if (ageDays <= 730) {
    score = 4;
  }

  return {
    score,
    newest_date: newestDate.toISOString(),
  };
}

const roleScores = {
  RECRUITER: 35,
  TECHNICAL_LEADER: 33,
  TECHNICAL_FOUNDER: 30,
  CEO_FOUNDER: 26,
  OTHER_EMPLOYEE: 15,
};

const hunterStatus =
  cleanText(verification.status).toLowerCase();

const hunterScore =
  Number(verification.score ?? 0);

const acceptAll =
  verification.accept_all === true;

const smtpCheck =
  verification.smtp_check === true;

let emailConfidence = 'LOW';
let emailVerificationScore = 0;

if (
  hunterStatus === 'valid' &&
  !acceptAll &&
  smtpCheck &&
  hunterScore >= 80
) {
  emailConfidence = 'HIGH';
  emailVerificationScore = 15;
} else if (hunterStatus === 'valid') {
  emailConfidence = 'MEDIUM';
  emailVerificationScore = 10;
} else if (
  hunterStatus === 'accept_all' ||
  hunterStatus === 'unknown'
) {
  emailConfidence = 'LOW';
  emailVerificationScore = 4;
} else {
  emailConfidence = 'NONE';
  emailVerificationScore = 0;
}

const roleRelevanceScore =
  roleScores[candidate.role_category] ?? 15;

const companyConfirmationScore =
  candidate.current_company_confirmed === true
    ? 25
    : 0;

let hiringConnectionScore = 0;

if (candidate.vacancy_connection === true) {
  hiringConnectionScore = 15;
} else if (
  candidate.general_hiring_connection === true
) {
  hiringConnectionScore = 8;
}

const freshness =
  calculateFreshness(candidate.source_ids);

const contactScore = Math.min(
  100,
  roleRelevanceScore +
    companyConfirmationScore +
    hiringConnectionScore +
    emailVerificationScore +
    freshness.score
);

return {
  json: {
    ...candidate,

    hunter_status: hunterStatus,
    hunter_score: hunterScore,
    hunter_accept_all: acceptAll,
    hunter_smtp_check: smtpCheck,

    email_confidence: emailConfidence,

    role_relevance_score:
      roleRelevanceScore,

    company_confirmation_score:
      companyConfirmationScore,

    hiring_connection_score:
      hiringConnectionScore,

    email_verification_score:
      emailVerificationScore,

    evidence_freshness_score:
      freshness.score,

    newest_evidence_date:
      freshness.newest_date,

    contact_score:
      contactScore,

    source_type:
      'BRAVE_HUNTER_FOUND_VERIFIED',

    research_status:
      'FOUND',

    last_checked:
      new Date().toISOString(),
  },
};

function cleanText(value) {
  return String(value ?? '')
    .replace(/\s+/g, ' ')
    .trim();
}

let candidate = $json ?? {};

// Recover the candidate if the IF node did not preserve everything.
if (!candidate.contact_name) {
  try {
    candidate =
      $('Attach Found Email').item.json ?? {};
  } catch {
    candidate = {};
  }
}

if (!candidate.contact_name) {
  throw new Error(
    'Unable to reconnect the no-email result to its candidate.'
  );
}

const evidencePackage =
  $('Prepare Contact Evidence').first().json;

const evidenceSources =
  Array.isArray(evidencePackage.evidence_sources)
    ? evidencePackage.evidence_sources
    : [];

const evidenceById = new Map(
  evidenceSources.map(source => [
    cleanText(source.source_id),
    source,
  ])
