function calculateFreshness(sourceIdsValue) {
  const sourceIds = cleanText(sourceIdsValue)
    .split('|')
    .map(value => value.trim())
    .filter(Boolean);

  const dates = [];

  for (const sourceId of sourceIds) {
    const rawDate = cleanText(
      evidenceById.get(sourceId)?.source_page_age
    );

    if (!rawDate) {
      continue;
    }

    const parsedDate = new Date(rawDate);

    if (!Number.isNaN(parsedDate.getTime())) {
      dates.push(parsedDate);
    }
  }

  if (dates.length === 0) {
    return {
      score: 4,
      newest_date: '',
    };
  }

  dates.sort((a, b) => b - a);

  const newestDate = dates[0];

  const ageDays =
    (Date.now() - newestDate.getTime()) /
    (1000 * 60 * 60 * 24);

  let score = 1;

  if (ageDays <= 90) {
    score = 10;
  } else if (ageDays <= 365) {
    score = 7;
  } else if (ageDays <= 730) {
    score = 4;
  }

  return {
    score,
    newest_date: newestDate.toISOString(),
  };
}

