  if (
    /^https?:\/\/(www\.)?linkedin\.com\/(posts|feed\/update)\//i
      .test(url) ||
    /linkedin\.com\/.*activity-/i.test(url)
  ) {
    return 'LINKEDIN_POST';
  }

  if (
    domain === companyDomain ||
    domain.endsWith(`.${companyDomain}`)
  ) {
    return 'COMPANY_SITE';
  }

  if (
    result?.subtype === 'article' ||
    result?.article
  ) {
    return 'ARTICLE';
  }

  if (
    /(github\.com|scholar\.google|researchgate\.net|orcid\.org)/i
