function extractJsonObject(text) {
  const input =
    cleanText(text)
      .replace(/^```(?:json)?\s*/i, '')
      .replace(/\s*```$/i, '')
      .trim();

  const start =
    input.indexOf('{');

  if (start === -1) {
    throw new Error(
      'The model response does not contain a JSON object.'
    );
  }

  let depth = 0;
  let insideString = false;
  let escaped = false;

  for (
    let index = start;
    index < input.length;
    index++
  ) {
    const character =
      input[index];

    if (insideString) {
      if (escaped) {
        escaped = false;
        continue;
      }

      if (character === '\\') {
        escaped = true;
        continue;
      }

      if (character === '"') {
        insideString = false;
      }

      continue;
    }

    if (character === '"') {
      insideString = true;
      continue;
    }

    if (character === '{') {
      depth++;
    }

    if (character === '}') {
      depth--;

      if (depth === 0) {
        return input.slice(
          start,
          index + 1
        );
      }
    }
  }

  throw new Error(
    'The model response contains an incomplete JSON object.'
  );
}


function getRawModelOutput(result) {
  const possibleValues = [
    result.text,
    result.output,
    result.response,
    result.content,
    result.message,
  ];

  for (const value of possibleValues) {
    if (
      typeof value === 'string' &&
      value.trim()
    ) {
      return value;
    }

    if (
      value &&
      typeof value === 'object' &&
      !Array.isArray(value)
    ) {
      return JSON.stringify(value);
    }
  }

  return JSON.stringify(result);
}


