  if (
    outreachMode === 'POST_APPLICATION'
  ) {
    return (
      `Hi ${contactFirstName}, ` +
      `I recently applied to ${companyName} ` +
      `and would be glad to connect regarding ` +
      `the opportunity.`
    );
  }

  if (
    outreachMode === 'ADJACENT_ROLE'
  ) {
    return (
      `Hi ${contactFirstName}, ` +
      `I came across ${companyName}'s work and ` +
      `am exploring early-career AI and data ` +
      `opportunities that may fit my profile. ` +
      `I'd be glad to connect.`
    );
  }

  return (
    `Hi ${contactFirstName}, ` +
    `I'm an early-career Big Data & AI Engineer ` +
    `interested in ${companyName}'s work and ` +
    `possible opportunities. I'd be glad to connect.`
  );
}


if (connectionNote.length > 240) {
  connectionNote =
    buildConnectionFallback();
}


/*
 * The company name itself could be unusually long.
 */
if (connectionNote.length > 240) {
  connectionNote =
    (
      `Hi ${contactFirstName}, ` +
      `I'm an early-career Big Data & AI Engineer ` +
      `exploring relevant AI and data opportunities. ` +
      `I'd be glad to connect.`
    );
}
/*
 * Remove unnecessary LinkedIn signatures because
 * LinkedIn already displays the sender's identity.
 */
linkedinMessage =
  linkedinMessage
    .replace(
      /\n\s*(?:Thanks|Best|Best regards|Kind regards|Regards|Sincerely)[,\s]*\n\s*YOUR_NAME\s*$/i,
      ''
    )
    .trim();


function buildLinkedInMessageFallback() {
  const portfolioUrl =
    cleanText(
