      `opportunity aligned with my background.` +
      (
        portfolioUrl
          ? ` My work is available at ${portfolioUrl}.`
          : ''
      )
    );
  }

  return (
    `Hi ${contactFirstName},\n\n` +
    `I am an early-career Big Data & AI Engineer with ` +
