    `upcoming opportunity aligned with my background.` +
    (
      portfolioUrl
        ? ` My work is available at ${portfolioUrl}.`
        : ''
    )
  );
}


if (linkedinMessage.length > 700) {
  linkedinMessage =
    buildLinkedInMessageFallback();
}

const combinedDraftText = [
  emailSubject,
  emailBody,
  connectionNote,
  linkedinMessage,
].join('\n');


/*
 * Detect application claims even though the simplified
 * prompt no longer returns application_reference_used.
 */
const applicationClaimPatterns = [
  /\bi (?:recently )?applied\b/i,
  /\bi (?:recently )?submitted my application\b/i,
  /\bmy application\b/i,
  /\bfollow(?:ing)? up on (?:my|the) application\b/i,
  /\bapplication follow-up\b/i,
];


const applicationReferenceUsed =
  parsed.application_reference_used === true ||
  applicationClaimPatterns.some(
    pattern =>
      pattern.test(
        combinedDraftText
      )
  );


const resumeReferenceUsed =
  parsed.resume_reference_used === true ||
  (
    /\b(?:attached|enclosed) (?:my )?(?:resume|cv)\b/i
      .test(combinedDraftText)
    ||
    /\bmy (?:resume|cv) is attached\b/i
      .test(combinedDraftText)
  );


const validationWarnings = [];
const finalIssues = [];


for (const field of missingFields) {
  finalIssues.push(
    `Required draft field is missing: ${field}.`
  );
}


/*
 * A non-applied or adjacent opportunity must never
 * imply that YOUR_NAME submitted an application.
 */
if (
  !canReferenceApplication &&
  applicationReferenceUsed
) {
  finalIssues.push(
    'The draft claims or implies that the candidate ' +
    'applied, but this opportunity is not marked APPLIED.'
  );
}


/*
 * Adjacent outreach must explicitly ask about a more
 * suitable early-career or upcoming opportunity.
 */
if (
  outreachMode === 'ADJACENT_ROLE'
) {
  const adjacentLanguagePresent =
    (
      /early-career|junior|adjacent|upcoming|future opportunit|better-fitting|profile like mine|aligned with my profile/i
    ).test(combinedDraftText);

  if (!adjacentLanguagePresent) {
    finalIssues.push(
      'The adjacent-role draft must ask about an ' +
      'early-career, adjacent, better-fitting, or ' +
      'upcoming opportunity.'
    );
  }

  const exactFitClaimPresent =
    (
      /\bperfect fit\b|\bideal fit\b|\bstrong fit\b|\bexact match\b/i
    ).test(combinedDraftText);

  if (exactFitClaimPresent) {
    finalIssues.push(
      'The adjacent-role draft presents the candidate ' +
      'as an exact fit for the advertised senior role.'
    );
  }
}


const emailWordCount =
  emailBody
    ? emailBody
        .split(/\s+/)
        .filter(Boolean)
        .length
    : 0;


/*
 * Use a broad practical range so concise, valid messages
 * are not unnecessarily rejected.
 */
if (
  emailBody &&
  (
    emailWordCount < 80 ||
    emailWordCount > 230
  )
) {
  finalIssues.push(
    `Email body contains ${emailWordCount} words; ` +
    'expected approximately 80–230.'
  );
}


if (connectionNote.length > 240) {
  finalIssues.push(
    `LinkedIn connection note is ` +
    `${connectionNote.length} characters; ` +
    'maximum is 240.'
  );
}


if (linkedinMessage.length > 700) {
  finalIssues.push(
    `LinkedIn message is ` +
    `${linkedinMessage.length} characters; ` +
    'maximum is 700.'
  );
}


const parseStatus =
  missingFields.length === 0
    ? 'PARSED'
    : 'NEEDS_REVIEW';


const draftFinalStatus =
  finalIssues.length === 0
    ? 'READY'
    : 'NEEDS_REVIEW';


