const request =
  $('Normalize Contact Research Request')
    .first()
    .json ?? {};

const clean = value =>
  String(value ?? '').trim();

const upper = value =>
  clean(value).toUpperCase();

const rows = $input
  .all()
  .map(item => item.json ?? {})
  .filter(
    row => clean(row.opportunity_key)
  );

const requestedKey =
  clean(
    request.requested_opportunity_key
  );

const triggerSource =
  clean(request.trigger_source) ||
  'MANUAL';


function blocked(
  reason,
  opportunityKey = requestedKey,
  extra = {},
) {
  return [
    {
      json: {
        selection_ready: false,
        selection_reason: reason,

        opportunity_key:
          opportunityKey,

        trigger_source:
