        selection_checked_at:
          new Date().toISOString(),

        ...extra,
      },
    },
  ];
}


function normalizeDomain(value) {
  let domain =
    clean(value).toLowerCase();

  if (!domain) {
    return '';
  }

  domain = domain
    .replace(/^https?:\/\//, '')
    .split('/')[0]
    .split('?')[0]
    .split('#')[0]
    .replace(/^www\./, '')
    .replace(/\.$/, '');

  return domain;
}


function normalizeEmail(value) {
  return clean(value).toLowerCase();
}


function normalizeLinkedIn(value) {
  return clean(value)
    .toLowerCase()
    .split('?')[0]
    .split('#')[0]
    .replace(/\/+$/, '');
}


function normalizeCompanyName(value) {
  return clean(value)
    .toLowerCase()
    .replace(/\s+/g, ' ');
}


function sharesCampaignIdentity(
  first,
  second,
) {
  const firstDomain =
    normalizeDomain(
      first.company_domain
    );

  const secondDomain =
    normalizeDomain(
      second.company_domain
    );

  if (
    firstDomain &&
    secondDomain &&
    firstDomain === secondDomain
  ) {
    return true;
  }


  const firstEmail =
    normalizeEmail(
      first.contact_email
    );

  const secondEmail =
    normalizeEmail(
      second.contact_email
    );

  if (
    firstEmail &&
    secondEmail &&
    firstEmail === secondEmail
  ) {
    return true;
  }


  const firstLinkedIn =
    normalizeLinkedIn(
      first.contact_linkedin_url
    );

  const secondLinkedIn =
    normalizeLinkedIn(
      second.contact_linkedin_url
    );

  if (
    firstLinkedIn &&
    secondLinkedIn &&
    firstLinkedIn === secondLinkedIn
  ) {
    return true;
  }


  /*
   * Company name is only a fallback when
   * neither row has a usable company domain.
   */
  if (
    !firstDomain &&
    !secondDomain
  ) {
    const firstCompany =
      normalizeCompanyName(
        first.company_name
      );

    const secondCompany =
      normalizeCompanyName(
        second.company_name
      );

    if (
      firstCompany &&
      secondCompany &&
      firstCompany === secondCompany
    ) {
      return true;
    }
  }

  return false;
}


function campaignRank(candidate) {
  const outreachStatus =
    upper(candidate.outreach_status);

  const researchStatus =
    upper(
      candidate.contact_research_status
    );

  const outreachApproval =
    upper(
      candidate.outreach_approval
    );

  const sentAt =
    clean(candidate.sent_at);


  if (
    sentAt ||
    [
      'SENT',
      'REPLIED',
      'FOLLOW_UP_DUE',
    ].includes(outreachStatus)
  ) {
    return 500;
  }


  if (
    outreachApproval === 'APPROVED' ||
    outreachStatus === 'APPROVED'
  ) {
    return 400;
  }


  if (
    outreachStatus === 'DRAFT_READY'
  ) {
    return 300;
  }


  if (
    researchStatus === 'COMPLETED'
  ) {
    return 200;
  }


  if (
    researchStatus === 'IN_PROGRESS'
  ) {
    return 100;
  }


  return 0;
}


function findCanonicalCampaign(
  targetRow,
) {
  const targetKey =
    clean(
      targetRow.opportunity_key
    );

  const candidates =
    rows
      .filter(candidate => {
        const candidateKey =
          clean(
            candidate.opportunity_key
          );

        if (
          !candidateKey ||
          candidateKey === targetKey
        ) {
          return false;
        }

        return (
          sharesCampaignIdentity(
            targetRow,
            candidate,
          ) &&
          campaignRank(candidate) > 0
        );
      })
      .sort(
        (first, second) => {
          const rankDifference =
            campaignRank(second) -
            campaignRank(first);

          if (rankDifference) {
            return rankDifference;
          }

          const sentDifference =
            clean(second.sent_at)
              .localeCompare(
                clean(first.sent_at)
              );

          if (sentDifference) {
            return sentDifference;
          }

          return clean(
            first.opportunity_key
          ).localeCompare(
            clean(
              second.opportunity_key
            )
          );
        },
      );

  return candidates[0] ?? null;
}


function effectiveOutreachMode(row) {
  const applicationStatus =
    upper(row.application_status);

  const storedMode =
    upper(row.outreach_mode);

  if (storedMode) {
    return storedMode;
  }

  if (
    applicationStatus === 'APPLIED'
  ) {
    return 'POST_APPLICATION';
  }

  return '';
}


function validateRow(row) {
  const opportunityKey =
    clean(row.opportunity_key);

  const applicationStatus =
    upper(row.application_status);

  const outreachMode =
    effectiveOutreachMode(row);

  const contactResearchStatus =
    upper(
      row.contact_research_status
    );

  const sentAt =
    clean(row.sent_at);

  const outreachStatus =
    upper(row.outreach_status);


  if (
    opportunityKey.startsWith(
      'test::'
    )
  ) {
    return {
      reason:
        'Test opportunities cannot launch ' +
        'production contact research.',

      extra: {
        duplicate_campaign: false,
      },
    };
  }


  const eligibleForResearch =
    applicationStatus === 'APPLIED' ||
    outreachMode ===
      'ADJACENT_ROLE' ||
    outreachMode ===
      'SPECULATIVE';


  if (!eligibleForResearch) {
    return {
      reason:
        'Contact research requires an APPLIED ' +
        'opportunity or an explicitly selected ' +
        'ADJACENT_ROLE or SPECULATIVE outreach mode.',

      extra: {
        duplicate_campaign: false,
      },
    };
  }


  if (
    sentAt ||
    outreachStatus === 'SENT'
  ) {
    return {
      reason:
        'Outreach was already sent for this opportunity.',

      extra: {
        duplicate_campaign: false,
      },
    };
  }


  /*
   * Check company-level coverage before the
   * row's own research status. This ensures
   * duplicate rows clearly report the company
   * campaign that covers them.
   */
  const canonicalCampaign =
    findCanonicalCampaign(row);


  if (canonicalCampaign) {
    const canonicalCompany =
      clean(
        canonicalCampaign.company_name
      ) ||
      clean(row.company_name) ||
      'This company';

    const canonicalPosition =
      clean(
        canonicalCampaign.position_title
      ) ||
      'another opportunity';

    const canonicalContact =
      clean(
        canonicalCampaign.contact_name
      ) ||
      clean(
        canonicalCampaign.contact_email
      ) ||
      'the saved company contact';

    const canonicalStatus =
      upper(
        canonicalCampaign.outreach_status
      ) ||
      upper(
        canonicalCampaign
          .contact_research_status
      ) ||
      'ACTIVE';

    return {
      reason:
        `${canonicalCompany} already has an ` +
        'active company outreach campaign.',

      extra: {
        duplicate_campaign: true,

        covered_by_opportunity_key:
          clean(
            canonicalCampaign
              .opportunity_key
          ),

        covered_by_company_name:
          canonicalCompany,

        covered_by_position_title:
          canonicalPosition,

        covered_by_contact:
          canonicalContact,

        covered_by_status:
          canonicalStatus,
      },
    };
  }


  if (
    contactResearchStatus &&
    contactResearchStatus !==
      'NOT_STARTED'
  ) {
    return {
      reason:
        'Contact research has already started or completed. ' +
        `Current status: ${contactResearchStatus}.`,

      extra: {
        duplicate_campaign: false,
      },
    };
  }


  return null;
}


let selectedRow = null;


if (requestedKey) {
  selectedRow =
    rows.find(
      row =>
        clean(
          row.opportunity_key
        ) === requestedKey
    ) ?? null;


  if (!selectedRow) {
    return blocked(
      'The requested opportunity was not found.'
    );
  }


  const validationResult =
    validateRow(selectedRow);


  if (validationResult) {
    return blocked(
      validationResult.reason,

      clean(
        selectedRow.opportunity_key
      ),

      validationResult.extra,
    );
  }
} else {
  selectedRow =
    rows.find(
      row => !validateRow(row)
    ) ?? null;


  if (!selectedRow) {
    return blocked(
      'No opportunity is currently eligible ' +
      'for contact research.',
      '',
      {
        duplicate_campaign: false,
      },
    );
  }
}


